"""Fill the generated tables and figures of the manuscript and supplement from committed outputs (M4).

Tables live between markers in the Markdown sources:

    <!-- BEGIN TABLE <name> (generated by scripts/m4_tables.py; do not edit) -->
    ...
    <!-- END TABLE <name> -->

Only the text between the markers is replaced. Every number comes from results/confirmatory/
(analysis.json, comparison.json, arm_summary.csv) or, for tables labelled exploratory, from
results/exploratory/M4-SENS/m4_exploratory.json. Figures are copied from the experiment folders,
and the exploratory sampling-interval figure is drawn with market.frozen_analysis.forest_svg.

    .venv/bin/python scripts/m4_tables.py
"""

from __future__ import annotations

import csv
import json
import re
import shutil
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))

from market.frozen_analysis import forest_svg  # noqa: E402

RES = ROOT / "results" / "confirmatory"
EX = json.loads((ROOT / "results" / "exploratory" / "M4-SENS" / "m4_exploratory.json").read_text())
FIG = ROOT / "research" / "paper" / "figures"


def g(x, nd=4) -> str:
    if x is None:
        return "n/a"
    if isinstance(x, bool):
        return str(x)
    if isinstance(x, int):
        return f"{x:,}"
    if x == 0:
        return "0"
    return f"{x:.{nd}g}"


def ci(lo, hi) -> str:
    return f"[{g(lo)}, {g(hi)}]"


def A(exp: str) -> dict:
    return json.loads((RES / exp / "analysis.json").read_text())["result"]


def arm_rows(exp: str) -> list[dict]:
    return list(csv.DictReader((RES / exp / "tables" / "arm_summary.csv").open()))


def table(head: list[str], rows: list[list[str]]) -> list[str]:
    return ["| " + " | ".join(head) + " |", "| " + " | ".join("---" for _ in head) + " |", *("| " + " | ".join(r) + " |" for r in rows)]


def t_expected_observed() -> list[str]:
    a1, a2, a3, a4 = A("EXP-001"), A("EXP-002"), A("EXP-003"), A("EXP-004")
    c5 = json.loads((RES / "EXP-005" / "comparison.json").read_text())
    p1, p2, p3 = a1["primary"], a2["primary"], a3["primary"]
    pl = a4["placebo"]
    inter = [r for r in a2["secondary_holm"] if r["metric"] == "vci (interaction)"][0]
    hv = c5["heldout_check"]["vci_values"]
    rows = [
        ["EXP-001 (primary, confirmatory)", "VCI(A1) - VCI(A0) > 0 (trend followers raise clustering)",
         f"{g(p1['mean_diff'])} {ci(p1['ci95_low'], p1['ci95_high'])}, d_z {g(p1['d_z'], 3)}, {p1['n_pairs']} pairs", f"{p1['verdict']} (H1 not supported)"],
        ["EXP-002 (primary)", "spread(low-ZI) - spread(high-ZI) > 0",
         f"{g(p2['mean_diff'])} price units {ci(p2['ci95_low'], p2['ci95_high'])}, d_z {g(p2['d_z'], 3)}, {p2['n_pairs']} pairs", f"{p2['verdict']}"],
        ["EXP-002 (secondary, Holm)", "interaction on VCI, nondirectional",
         f"{g(inter['mean_diff'])}, Holm interval {ci(inter['holm_ci_low'], inter['holm_ci_high'])}", "nonzero (secondary)"],
        ["EXP-003 (primary, optional)", "drawdown(S-ZI+TF) - drawdown(S-ZI) > 0",
         f"{g(p3['mean_diff'])} {ci(p3['ci95_low'], p3['ci95_high'])}, d_z {g(p3['d_z'], 3)}, {p3['n_pairs']} pairs", f"{p3['verdict']}"],
        ["EXP-004 placebo", "VCI(A1) - VCI(A4) > 0 (feedback beyond aggressiveness)",
         f"{g(pl['mean_diff'])} {ci(pl['ci95_low'], pl['ci95_high'])}", f"{pl['verdict']}; attribution rule not triggered (EXP-001 inconclusive)"],
        ["EXP-004 robustness rule", "same sign and interval excluding 0 at dt 10, dt 200 and tick 2",
         "; ".join(f"{r['role'].replace('sampling interval ', '')}: {g(r['mean_diff'])} {ci(r['ci95_low'], r['ci95_high'])}" for r in [*a4["dt"], a4["tick2"]]),
         a4["robustness_rule"]],
        ["EXP-005 (a)", "held-out day: VCI > 0 in each of 5 stocks",
         ", ".join(g(v) for v in hv), "not supported (one stock below 0)" if not c5["heldout_check"]["vci_positive_all"] else "supported"],
        ["EXP-005 (b)", "no directional expectation (descriptive placement)", "see Table 7", "descriptive"],
    ]
    return table(["Experiment", "Prediction (frozen)", "Observation (95% percentile bootstrap interval)", "Verdict under the frozen rule"], rows)


def t_exp001_arms() -> list[str]:
    rows = []
    for r in arm_rows("EXP-001"):
        f = lambda k: f"{g(float(r[k + '_mean']))} ({g(float(r[k + '_sd']))})"  # noqa: E731
        rows.append([r["arm"], r["runs"], f("vci"), f("realised_volatility"), f("excess_kurtosis"), f("return_acf1"), f("mean_spread"),
                     f("mean_depth_at_best"), f("max_drawdown")])
    return table(["Arm", "Runs", "VCI", "Realised volatility", "Excess kurtosis", "acf(r, 1)", "Mean spread (ticks)", "Depth at best (units)",
                  "Max drawdown (fraction)"], rows)


def t_exp001_secondary_vci() -> list[str]:
    a = A("EXP-001")
    rows = []
    for r in a["secondary_holm"]:
        if r["metric"] in ("vci", "realised_volatility", "max_drawdown", "return_acf1"):
            rows.append([f"{r['treatment']} - {r['control']}", r["metric"], g(r["mean_diff"]), g(r["d_z"], 3), ci(r["ci95_low"], r["ci95_high"]),
                         ci(r["holm_ci_low"], r["holm_ci_high"]), "< 0.0001" if r["p_holm"] == 0 else g(r["p_holm"], 3)])
    return table(["Contrast", "Metric", "Mean diff.", "d_z", "95% interval", "Holm interval (D-013)", "Holm p"], rows)


def t_exp004() -> list[str]:
    a = A("EXP-004")
    rows = []
    for r in [a["placebo"], a["a4_minus_a0"], a["tick2"], *a["dt"], a["exclusion"]]:
        rows.append([r["role"], f"{r['treatment']} - {r['control']}", r["metric"], str(r["n_pairs"]), g(r["mean_diff"]), g(r["d_z"], 3),
                     ci(r["ci95_low"], r["ci95_high"])])
    return table(["Component", "Contrast", "Metric", "Pairs", "Mean diff.", "d_z", "95% interval"], rows)


def t_dt_grid() -> list[str]:
    e1 = EX["part1"]["E1_vci_dt_grid"]
    by = {(r["contrast"], r["dt"]): r for r in e1}
    rows = []
    for dt in EX["part1"]["dt_grid"]:
        cell = lambda c: f"{g(by[(c, dt)]['mean'])} {ci(by[(c, dt)]['ci95_low'], by[(c, dt)]['ci95_high'])}"  # noqa: E731
        rows.append([str(dt), cell("A1 - A0"), cell("A4 - A0"), cell("A1 - A4"), cell("A2 - A0")])
    return table(["dt (steps)", "A1 - A0 (trend)", "A4 - A0 (placebo)", "A1 - A4 (feedback beyond aggressiveness)", "A2 - A0 (mean reversion)"], rows)


def t_shock_did() -> list[str]:
    e2 = EX["part1"]["E2_unshocked_control_window"]
    rows = []
    for k, v in e2.items():
        if k.startswith("arm means"):
            continue
        rows.append([k, str(v["n"]), g(v["mean"]), g(v["d_z"], 3), ci(v["ci95_low"], v["ci95_high"])])
    return table(["Contrast (window drawdown from step 50,000, fraction of the step-49,999 mid)", "Pairs", "Mean diff.", "d_z", "95% interval"], rows)


def t_exp005() -> list[str]:
    c5 = json.loads((RES / "EXP-005" / "comparison.json").read_text())
    rows = []
    for r in c5["arms"]:
        if r["sampling"] != "primary":
            continue
        rows.append([r["arm"], r["statistic"], g(r["sim_mean"]), ci(r["ci95_low"], r["ci95_high"]), g(r["ref_median"]), ci(r["ref_min"], r["ref_max"]),
                     r["placement"]])
    return table(["Arm", "Statistic", "Arm mean", "95% interval", "FI-2010 median", "FI-2010 [min, max]", "Placement"], rows)


def t_holm_conservative() -> list[str]:
    e3 = EX["part2"]["E3_holm_conservative_ties"]
    rows = []
    for exp, v in e3.items():
        rows.append([exp, str(v["m"]), str(v["tied_at_p0"]), str(v["all_still_exclude_0"])])
    return table(["Experiment", "Family size m", "Contrasts tied at p = 0", "All still exclude 0 at level 1 - 0.05/m"], rows)


def t_rule_reading() -> list[str]:
    e4 = EX["part2"]["E4_robustness_rule_H1_reference"]
    rows = [[r["component"], g(r["mean_diff"]), ci(*r["ci95"]), str(r["same_sign_as_H1"]), str(r["ci_excludes_0"])] for r in e4["rows"]]
    rows.append(["reading with the H1 sign as reference (exploratory)", "", "", "", e4["reading"]])
    rows.append(["frozen reading (D-013: sign of the EXP-001 point estimate)", "", "", "", e4["frozen_reading"]])
    return table(["Component", "Mean diff.", "95% interval", "Same sign as H1 (> 0)", "Interval excludes 0"], rows)


def t_exp002_arms() -> list[str]:
    rows = []
    for r in arm_rows("EXP-002"):
        f = lambda k: f"{g(float(r[k + '_mean']))} ({g(float(r[k + '_sd']))})"  # noqa: E731
        rows.append([r["arm"], r["runs"], r["degenerate"], f("mean_spread"), f("mean_depth_at_best"), f("vci"), f("max_drawdown")])
    return table(["Arm", "Runs", "Flagged", "Mean spread (ticks)", "Depth at best (units)", "VCI", "Max drawdown"], rows)


def t_exp003_arms() -> list[str]:
    a = A("EXP-003")
    rows = []
    for arm in ("S-ZI", "S-ZI+TF", "S-ZI+MR"):
        km, sh = a["recovery_kaplan_meier"][arm], a["shock_covariates"][arm]
        rows.append([arm, str(km["n"]), str(km["events"]), str(km["censored"]), g(km["median_steps"]) if km["median_steps"] is not None else "n/a",
                     f"{g(sh['bid_depth_at_shock_mean'])} ({g(sh['bid_depth_at_shock_sd'])})"])
    return table(["Arm", "Runs", "Recovered", "Censored at 20,000 steps", "Kaplan-Meier median (steps)", "Bid depth at shock, mean (SD)"], rows)


TABLES = {
    "expected_observed": t_expected_observed,
    "exp001_arms": t_exp001_arms,
    "exp001_secondary": t_exp001_secondary_vci,
    "exp002_arms": t_exp002_arms,
    "exp003_arms": t_exp003_arms,
    "exp004": t_exp004,
    "dt_grid": t_dt_grid,
    "shock_did": t_shock_did,
    "exp005": t_exp005,
    "holm_conservative": t_holm_conservative,
    "rule_reading": t_rule_reading,
}


def fill(path: Path) -> list[str]:
    text = path.read_text()
    done = []
    for name, fn in TABLES.items():
        pat = re.compile(rf"(<!-- BEGIN TABLE {name} [^>]*-->)\n(?:.*?\n)?(<!-- END TABLE {name} -->)", re.S)
        if pat.search(text):
            text = pat.sub(lambda m: m.group(1) + "\n" + "\n".join(fn()) + "\n" + m.group(2), text)
            done.append(name)
    path.write_text(text)
    return done


def figures() -> None:
    FIG.mkdir(parents=True, exist_ok=True)
    for exp, name in (("EXP-001", "vci_paired_diff"), ("EXP-001", "vci_by_arm"), ("EXP-001", "mid_paths"), ("EXP-004", "frozen_contrasts"),
                      ("EXP-003", "frozen_contrasts"), ("EXP-005", "placement")):
        shutil.copyfile(ROOT / "research" / "experiments" / exp / "figures" / f"{name}.svg", FIG / f"{exp}_{name}.svg")
    rows = []
    for r in EX["part1"]["E1_vci_dt_grid"]:
        if r["contrast"] in ("A1 - A0", "A1 - A4"):
            t, c = r["contrast"].split(" - ")
            rows.append({"treatment": t, "control": c, "metric": f"VCI dt {r['dt']}", "mean_diff": r["mean"], "ci95_low": r["ci95_low"],
                         "ci95_high": r["ci95_high"]})
    forest_svg(FIG / "M4_exploratory_dt_grid.svg", rows, "EXPLORATORY: VCI contrasts across sampling intervals (development seeds 101-130)",
               "Mean paired VCI difference over 30 development seeds (red dot) and 95% percentile bootstrap interval (blue line) for A1 minus A0 "
               "and A1 minus A4 at dt 5 to 500 steps; dashed line at 0. Exploratory, not confirmatory.")


def main() -> int:
    figures()
    for rel in ("research/paper/manuscript.md", "research/paper/supplementary.md"):
        print(rel, fill(ROOT / rel))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
